-- Fix BUG B: Injeção de dados 16-17/08 FAHTO
-- Removendo dados parciais/duplicados para garantir integridade do backfill
DELETE FROM traffic_data 
WHERE operation_id = '8707b3f8-ab41-4a63-902c-9ab97fe50c8a' 
  AND date IN ('2026-08-16', '2026-08-17');

-- Garantir que contas estão cadastradas
ON CONFLICT (account_id) DO UPDATE SET operation_id=EXCLUDED.operation_id, is_active=true;

-- Inserindo dados consolidados por conta (Unique Key forçada via DELETE prévio)
